slide4.corrected:
function batchTransfer(address[] to, uint value) external {
  uint total = value * to.length;
  if(total / to.length != value) {
    revert("overflow");
  }
  if(balances[msg.sender] < total) {
    revert("balance");
  }
  balances[msg.sender] -= total;
  for(uint i = 0; i < to.length; i++) {
    balances[to[i]] += value;
  }
}
